import{af as o,ad as n,z as h,J as d,ab as r,x as e,C as i,K as a,y as l}from"./chunks/framework.BnTFvF69.js";const y=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"devices/api/sdks/toit/getting-started.md","filePath":"devices/api/sdks/toit/getting-started.md"}'),c={name:"devices/api/sdks/toit/getting-started.md"};function g(u,s,k,b,m,F){const t=n("PluginTabsTab"),p=n("PluginTabs");return h(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793263979000"},[s[2]||(s[2]=r(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">⚠️ main branch documentation</p><p>This documentation is currently for the <code>main</code> branch of the Toit SDK, which is under active development.</p><p>There are pinned early releases available, but they may be out of date in comparison to this documentation.</p></div><h3 id="_1-get-an-esp32-enabled-device" tabindex="-1">1. Get an ESP32 enabled device <a class="header-anchor" href="#_1-get-an-esp32-enabled-device" aria-label="Permalink to &quot;1. Get an ESP32 enabled device&quot;">​</a></h3><p>ESP32s are being introduced on some Lightbug devices, such as the <a href="/docs/pr/30/devices/rtk/">RTK handheld (RH2)</a>.</p><p>You&#39;ll need one of these devices to run Toit code on.</p><h3 id="_2-install-jaguar" tabindex="-1">2. Install Jaguar <a class="header-anchor" href="#_2-install-jaguar" aria-label="Permalink to &quot;2. Install Jaguar&quot;">​</a></h3><p><a href="https://github.com/toitlang/jaguar" target="_blank" rel="noreferrer">Jaguar</a> is a small Toit application that runs on your ESP32 which comes with a command line tool that allows you to update and restart your ESP32 code written in Toit over WiFi, which is ideal for fast development.</p><p>Install Jaguar, <a href="https://docs.toit.io/getstarted/device/#2-install-jaguar" target="_blank" rel="noreferrer">following step 2</a> in the Toit getting started guide.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>We currently recommend <code>v1.55.0</code>+ of Jaguar, which bundles at least <code>v2.0.0-alpha.188</code> of Toit.</p></div><p>Once installed, you should be able to run the version command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Version:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">         v1.55.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SDK</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     v2.0.0-alpha.188</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> date:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      2025-08-20T08:35:24Z</span></span></code></pre></div><h3 id="_3-flash-the-esp" tabindex="-1">3. Flash the ESP <a class="header-anchor" href="#_3-flash-the-esp" aria-label="Permalink to &quot;3. Flash the ESP&quot;">​</a></h3><p>Now it is time to connect your ESP enabled Lightbug device with a USB cable to your computer, and flash the ESP32 with the Jaguar firmware.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>All ESP enabled Lightbug devices currently have ESP32C6 chips, so <code>--chip esp32c6</code> is required for flashing.</p></div><p>Running <code>jag flash --chip esp32c6</code> will ask you for the serial port to use, and the WiFi credentials, but be aware that the tooling requires <a href="https://github.com/toitlang/jaguar#permission-to-access-serial-port" target="_blank" rel="noreferrer">permission to access your serial port</a>.</p><p>It&#39;s possible to configure default WiFi credentials, see the <a href="https://docs.toit.io/getstarted/device/#3-flash-your-device" target="_blank" rel="noreferrer">Toit guide</a> for more info.</p><h3 id="_4-monitor-the-device" tabindex="-1">4. Monitor the device <a class="header-anchor" href="#_4-monitor-the-device" aria-label="Permalink to &quot;4. Monitor the device&quot;">​</a></h3><p>After flashing, your device boots up and starts the Toit virtual machine. The Jaguar service on the device starts a small HTTP server that listens for incoming requests.</p><p>You can see what the ESP is doing by monitoring the serial output of the device with the <code>jag monitor</code> command.</p><details><summary>Click to see example \`jag monitor\` output</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Starting serial monitor of port &#39;COM22&#39; ...</span></span>
<span class="line"><span>[wifi] DEBUG: connected</span></span>
<span class="line"><span>ESP-ROM:esp32c6-20220919</span></span>
<span class="line"><span>Build:Sep 19 2022</span></span>
<span class="line"><span>rst:0x15 (USB_UART_HPSYS),boot:0x6f (SPI_FAST_FLASH_BOOT)</span></span>
<span class="line"><span>Saved PC:0x4081306a</span></span>
<span class="line"><span>SPIWP:0xee</span></span>
<span class="line"><span>mode:DIO, clock dESP-ROM:esp32c6-20220919</span></span>
<span class="line"><span>Build:Sep 19 2022</span></span>
<span class="line"><span>rst:0x15 (USB_UART_HPSYS),boot:0x6f (SPI_FAST_FLASH_BOOT)</span></span>
<span class="line"><span>Saved PC:0x400294a2</span></span>
<span class="line"><span>SPIWP:0xee</span></span>
<span class="line"><span>mode:DIO, clock div:2</span></span>
<span class="line"><span>load:0x40875720,len:0x9c</span></span>
<span class="line"><span>load:0x4086c110,len:0xb94</span></span>
<span class="line"><span>load:0x4086e610,len:0x2534</span></span>
<span class="line"><span>entry 0x4086c110</span></span>
<span class="line"><span>[toit] INFO: starting &lt;v2.0.0-alpha.188&gt;</span></span>
<span class="line"><span>[toit] DEBUG: clearing RTC memory: powered on by hardware source</span></span>
<span class="line"><span>[toit] INFO: running on ESP32C6 - revision 0.1</span></span>
<span class="line"><span>[wifi] DEBUG: connecting</span></span>
<span class="line"><span>[wifi] DEBUG: connected</span></span>
<span class="line"><span>[wifi] INFO: network address dynamically assigned through dhcp {ip: 192.168.68.50}</span></span>
<span class="line"><span>[wifi] INFO: dns server address dynamically assigned through dhcp {ip: [8.8.8.8, 1.1.1.1]}</span></span>
<span class="line"><span>[jaguar.http] INFO: running Jaguar device &#39;long-expert&#39; (id: &#39;736b8804-dcdf-4d96-890a-8785c1bfa31d&#39;) on &#39;http://192.168.68.50:9000&#39;</span></span></code></pre></div></details><div class="tip custom-block"><p class="custom-block-title">⚡ Tip</p><p>Leave the terminal with <code>jag monitor</code> running open, as it will show you the output of the device, and will also show you the output of the code you run on the device.</p></div><h3 id="_5-start-a-project" tabindex="-1">5. Start a project <a class="header-anchor" href="#_5-start-a-project" aria-label="Permalink to &quot;5. Start a project&quot;">​</a></h3><p>Create a new directory for your project, and run the <code>jag pkg init</code> command to create a new Toit project.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-lightbug-project</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-lightbug-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>And install the latest version of the Toit Lightbug SDK, which contains the Toit code that runs on the Lightbug devices.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VERSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lightbug-io/toit-lightbug</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $3}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/lightbug-io/toit-lightbug@</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VERSION</span></span></code></pre></div><p>You can copy the example <a href="https://github.com/lightbug-io/toit-lightbug/blob/main/examples/modules/eink/element-box-text.toit" target="_blank" rel="noreferrer">eink based Hello World application</a> into your project with the following command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.packages/github.com/lightbug-io/toit-lightbug/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VERSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/examples/modules/eink/element-box-text.toit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./main.toit</span></span></code></pre></div><h3 id="_6-run-the-code" tabindex="-1">6. Run the code <a class="header-anchor" href="#_6-run-the-code" aria-label="Permalink to &quot;6. Run the code&quot;">​</a></h3><p>Use the <code>jag run</code> command to run the code on your device.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./main.toit</span></span></code></pre></div><p>If your device can not be found automatically, you can specify the device IP address in the command line with the <code>--device</code> flag.</p><p>Once the code is running, you should see some output through the <code>monitor</code> command you ran earlier.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[jaguar] INFO: program 970dfee5-ec68-d8ad-ade5-06b62aaad39b started</span></span>
<span class="line"><span>💬 Sending text to device</span></span></code></pre></div><p>And you should see the device screen update, saying <code>Lightbug...</code> in the top left.</p>`,35)),e(p,null,{default:i(()=>[e(t,{label:"Graphic"},{default:i(()=>[...s[0]||(s[0]=[a("figure",null,[a("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/imgur/8QP1022.png",alt:"",tabindex:"0"}),a("figcaption")],-1)])]),_:1}),e(t,{label:"Photo"},{default:i(()=>[...s[1]||(s[1]=[a("figure",null,[a("img",{src:"https://upload.r2.lb.chasm.cloud/2025/10/imgur/7ca0Nda.png",alt:"",width:"500",tabindex:"0"}),a("figcaption")],-1)])]),_:1})]),_:1}),s[3]||(s[3]=a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},"⚡ Tip"),a("p",null,[l("You can also see this code "),a("a",{href:"/docs/pr/30/devices/api/sdks/toit/examples/screen-text"},"under the examples section"),l(".")])],-1))])}const f=o(c,[["render",g]]);export{y as __pageData,f as default};
